desired = {"api-gw": {"replicas": 3, "image": "gw:1.4"}, "ingest": {"replicas": 2, "image": "ing:2.1"}}
actual = {"api-gw": {"replicas": 1, "image": "gw:1.4"}, "ingest": {"replicas": 2, "image": "ing:2.1"},
          "debug-pod": {"replicas": 1, "image": "busybox"}}
for name in sorted(set(desired) | set(actual)):
    d, a = desired.get(name), actual.get(name)
    if d == a:
        print(f"{name}: 같음")
    elif d is None:
        print(f"{name}: Git에 없음 → 지운다(prune)")
    else:
        diff = {k: (a.get(k), v) for k, v in d.items() if a.get(k) != v}
        print(f"{name}: 다름 {diff} → Git 쪽으로 되돌린다")
# 출력:
# api-gw: 다름 {'replicas': (1, 3)} → Git 쪽으로 되돌린다
# debug-pod: Git에 없음 → 지운다(prune)
# ingest: 같음

import math
docs = {"식각 장비 온도 이상 조치": [0.9, 0.1, 0.0],
        "배터리 셀 불량 분류": [0.1, 0.9, 0.2],
        "식각 챔버 점검 주기": [0.8, 0.0, 0.3]}
q = [1.0, 0.0, 0.1]   # '식각 온도 알람' 질문을 흉내 낸 벡터
def cos(a, b):
    return sum(x*y for x, y in zip(a, b)) / (math.sqrt(sum(x*x for x in a)) * math.sqrt(sum(y*y for y in b)))
for t, v in sorted(docs.items(), key=lambda kv: -cos(q, kv[1])):
    print(f"{cos(q, v):.3f}  {t}")
# 출력:
# 0.989  식각 장비 온도 이상 조치
# 0.967  식각 챔버 점검 주기
# 0.129  배터리 셀 불량 분류
